import { CardViewItem, InfoDrawerComponent, InfoDrawerContentDirective, InfoDrawerLayoutComponent, InfoDrawerTabComponent } from '@alfresco/adf-core';
import { Component, EventEmitter, Input, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { DocumentService, DocumentPropertiesService } from '@alfresco/adf-hx-content-services/services';
import { Observable, Subject } from 'rxjs';
import { take, finalize, filter, takeUntil } from 'rxjs/operators';
import { Document } from '@hylandsoftware/hxcs-js-client';
import { NgIf, AsyncPipe } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { TranslateModule } from '@ngx-translate/core';
import { PropertiesViewerContainerComponent } from '../properties-viewer-container/properties-viewer-container.component';

@Component({
    selector: 'hxp-properties-sidebar',
    templateUrl: './hxp-properties-sidebar.component.html',
    styleUrls: ['./hxp-properties-sidebar.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
    imports: [
        InfoDrawerLayoutComponent,
        InfoDrawerContentDirective,
        MatButtonModule,
        MatIconModule,
        InfoDrawerComponent,
        InfoDrawerTabComponent,
        NgIf,
        MatProgressSpinnerModule,
        PropertiesViewerContainerComponent,
        AsyncPipe,
        TranslateModule,
    ],
})
export class HxpPropertiesSidebarComponent implements OnInit {

    @Input() editable = true;
    @Input() document!: Document;
    @Output() closePropertySidebar = new EventEmitter();

    public propertyLoading = false;
    public selectedDocument!: Document;
    protected documentProperties$!: Observable<CardViewItem[]>;
    protected otherDocumentProperties$!: Observable<CardViewItem[]>;

    private readonly destroyed$: Subject<void> = new Subject<void>();

    constructor(
        private documentService: DocumentService,
        private documentPropertiesService: DocumentPropertiesService
    ) {
        this.subscribeToDocumentUpdates();
    }

    ngOnInit() {
        this.loadDocumentProperties(this.document.sys_id ?? '');
    }

    handlePropertyUpdate(propertyUpdated: boolean): void {
        if (propertyUpdated) {
            this.fetchDefaultProperties();
            this.fetchOtherProperties();
        }
    }

    onClose(): void {
        this.closePropertySidebar.emit();
    }

    private subscribeToDocumentUpdates(): void {
        this.documentService.documentUpdated$
            .pipe(
                filter(({ document }) => !!document && document.sys_id === this.document.sys_id),
                takeUntil(this.destroyed$)
            )
            .subscribe({
                next: () => {
                    this.loadDocumentProperties(this.document.sys_id ?? '');
                },
                error: (error) => console.error(error)
            });
    }

    private loadDocumentProperties(documentId: string): void {
        if (!documentId) {
            return;
        }

        this.propertyLoading = true;
        this.documentService.getDocumentById(documentId)
            .pipe(
                take(1),
                finalize(() => this.propertyLoading = false)
            )
            .subscribe({
                next: doc => {
                    this.selectedDocument = doc;
                    this.fetchDocumentProperties();
                },
                error: ({ error }) => {
                    console.error(error);
                }
            });
    }


    private fetchDocumentProperties(): void {
        if (!this.selectedDocument) {
            return;
        }

        this.documentPropertiesService.extractCustomSchemaFields(this.selectedDocument.sys_primaryType)
            .pipe(take(1))
            .subscribe({
                next: (schemaFields: Record<string, any>) => {
                    this.initializeDocumentWithSchema(schemaFields);
                },
                error: (error) => console.error(error)
            });

        this.fetchDefaultProperties();
        this.fetchOtherProperties();
    }


    private initializeDocumentWithSchema(
        schemaFields: Record<string, any>,
        currentDoc: Record<string, any> = this.selectedDocument
    ): void {
        for (const fieldName in schemaFields) {
            if (!currentDoc[fieldName]) {
                currentDoc[fieldName] = typeof schemaFields[fieldName] !== 'object' ? '' : {};
                if (typeof schemaFields[fieldName] === 'object') {
                    this.initializeDocumentWithSchema(
                        schemaFields[fieldName],
                        currentDoc[fieldName]
                    );
                }
            } else if (typeof schemaFields[fieldName] === 'object') {
                this.initializeDocumentWithSchema(
                    schemaFields[fieldName],
                    currentDoc[fieldName]
                );
            }
        }
    }

    private fetchDefaultProperties(): void {
        this.documentProperties$ =
            this.documentPropertiesService.getDefaultPropertiesFromDocument(
                this.selectedDocument
            );
    }

    private fetchOtherProperties(): void {
        this.otherDocumentProperties$ =
            this.documentPropertiesService.getPropertiesFromDocument(
                this.selectedDocument,
                {
                    exclude: {
                        schemas: ['sysfile_blob', 'sys_'],
                    },
                }
            );
    }
}

