import { Component, HostListener, Input } from '@angular/core';
import { MatDialogRef } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';

@Component({
    selector: 'hxp-permission-dialog-resizer',
    templateUrl: './permission-dialog-resizer.component.html',
    styleUrls: ['./permission-dialog-resizer.component.scss'],
    standalone: true,
    imports: [MatIconModule]
})
export class PermissionDialogResizerComponent {

    @Input() dialogRef!: MatDialogRef<any>;
    @Input() minWidth!: number;

    private width = 0;
    private previousPositionX = 0;
    private grabber = false;
    private dragging = false;

    @HostListener('document:mousemove', ['$event'])
    onMouseMove(event: MouseEvent) {
        if (!this.grabber || !this.dragging) {
            return;
        }
        event.stopPropagation();
        event.preventDefault();
        this.resizer(event.clientX - this.previousPositionX);
        this.previousPositionX = event.clientX;
    }

    @HostListener('document:mouseup', ['$event'])
    onMouseUp(event: MouseEvent) {
        if (!this.grabber && !this.dragging) {
            return;
        }
        event.stopPropagation();
        event.preventDefault();
        this.grabber = false;
        this.dragging = false;
    }

    @HostListener('document:mousedown', ['$event'])
    onMouseDown(event: MouseEvent) {
        if (!this.dragging) {
            return;
        }
        event.stopPropagation();
        event.preventDefault();
        this.grabber = true;
        this.previousPositionX = event.clientX;
    }

    startDrag(){
        this.dragging = true;
    }

    private resizer(offsetX: number) {
        const width = this.width - offsetX;
        this.width = width >= this.minWidth ? width : this.minWidth;
        this.dialogRef.updateSize(this.width + 'px', '100vh');
    }
}

