import { ChangeDetectionStrategy, Component, Inject, ViewEncapsulation } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { Document } from '@hylandsoftware/hxcs-js-client';
import { PermissionsManagementBaseComponent } from '../permissions-management-base/permissions-management-base.component';
import { DocumentService, PermissionsManagementDialogData, PermissionsManagementFacade, PermissionsManagementStateService } from '@alfresco/adf-hx-content-services/services';
import { filter } from 'rxjs/operators';
import { CancelPermissionDialogComponent, DismissPermissionDialogData } from '../cancel-permission-dialog/cancel-permission-dialog.component';
import { DialogConfig } from '../../../util/dialog/config';
import { ClosePermissionDialogComponent } from '../cancel-permission-dialog/close-permission-dialog.component';
import { PermissionDialogResizerComponent } from '../permission-dialog-resizer/permission-dialog-resizer.component';
import { NgIf, AsyncPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatDividerModule } from '@angular/material/divider';
import { MatIconModule } from '@angular/material/icon';
import { MatSnackBarModule } from '@angular/material/snack-bar';
import { MatTabsModule } from '@angular/material/tabs';
import { TranslateModule } from '@ngx-translate/core';
import { PermissionsSearchComponent } from '../permission-search/permission-search.component';
import { PermissionsDocumentTitleComponent } from '../permissions-document-title/permissions-document-title.component';
import { PermissionsTableComponent } from '../permissions-table/permissions-table.component';
import { PermissionsComponent } from '../permissions/permissions.component';
import { AddPermissionComponent } from '../add-permission/add-permission.component';

export const DIALOG_MIN_WIDTH = 380;

@Component({
    selector: 'hxp-permissions-management-dialog',
    templateUrl: './permissions-management-dialog.component.html',
    styleUrls: ['../permissions-management-base/permissions-management-base.component.scss', './permissions-management-dialog.component.scss'],
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
    imports: [
        PermissionDialogResizerComponent,
        MatDialogModule,
        PermissionsDocumentTitleComponent,
        MatIconModule,
        FormsModule,
        MatTabsModule,
        MatSnackBarModule,
        NgIf,
        PermissionsTableComponent,
        PermissionsSearchComponent,
        PermissionsComponent,
        AddPermissionComponent,
        MatDividerModule,
        MatButtonModule,
        AsyncPipe,
        TranslateModule,
    ],
    providers: [PermissionsManagementFacade, PermissionsManagementStateService],
})
export class PermissionsManagementDialogComponent extends PermissionsManagementBaseComponent {
    override document: Document;

    dialogMinWidth = DIALOG_MIN_WIDTH;

    constructor(
        @Inject(MAT_DIALOG_DATA) public data: PermissionsManagementDialogData,
        public dialogRef: MatDialogRef<PermissionsManagementDialogComponent>,
        permissionsManagementFacade: PermissionsManagementFacade,
        private documentService: DocumentService,
        private dialog: MatDialog
    ) {
        super(permissionsManagementFacade);
        this.document = data.document;
    }

    savePermissions() {
        this.saveDocumentPermissions()
            .pipe(filter(Boolean))
            .subscribe({
                next: () => {
                    this.documentService.requestReload();
                    this.dialogRef.close();
                },
            });
    }

    cancel() {
        if (!this.edited) {
            return this.dialogRef.close();
        }
        this.dialog.open<CancelPermissionDialogComponent, DismissPermissionDialogData<PermissionsManagementDialogComponent>>
            (CancelPermissionDialogComponent, {
                width: DialogConfig.small.width,
                data: {
                    dialogTitle: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_CANCEL_DIALOG.TITLE',
                    dialogDescription: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_CANCEL_DIALOG.DESCRIPTION',
                    dialogRejectButton: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_CANCEL_DIALOG.REJECT',
                    dialogConfirmButton: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_CANCEL_DIALOG.CONFIRM',
                    permissionDialogRef: this.dialogRef
                }
            });
    }

    closePermission() {
        if (!this.edited) {
            return this.dialogRef.close();
        }
        const closeDialogRef = this.dialog.open<ClosePermissionDialogComponent, DismissPermissionDialogData>
            (ClosePermissionDialogComponent, {
                width: DialogConfig.small.width,
                data: {
                    dialogTitle: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_SAVE_DIALOG.TITLE',
                    dialogDescription: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_SAVE_DIALOG.DESCRIPTION',
                    dialogRejectButton: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_SAVE_DIALOG.REJECT',
                    dialogConfirmButton: 'PERMISSIONS_MANAGEMENT_ACTION.ASK_TO_SAVE_DIALOG.CONFIRM'
                }
            });

        closeDialogRef.afterClosed().subscribe(result => {
            this.dialogRef.close();
            if (result.save) {
                this.savePermissions();
            }
        });
    }
}

